perspectives.style:
@controls {
  bottom {
    filter {
      target: connection;
      by: "connection type";
      as: labels;
      multiple: true;
      default: show-all;
    }
  }

  top {
    filter {
      target: element;
      by: "element type";
      as: labels;
      multiple: true;
      default: show-all;
    }
  }
}

@settings {
  template: stakeholder;
  theme: dark;
  layout: force;
  connection-color: #a7a7a7;
  renderer: canvas;
  layout-preset: hairball;
  element-scale: scale("degree", 0.5, 4);
}

/* Personagem */
element["element type"="PC"] {
  color: #54a159;
}

/* NPC */
element["element type"="NPC"] {
  color: #6aaed6;
}

/* Grupo */
element["element type"="Grupo"] {
  color: #f67c49;
  shape: pentagon;
}

/* Local */
element["element type"="Local"] {
  color: #97bd8a;
  shape: rectangle;
}

/* Monstro / Criatura / Boss */
element["element type"="Monstro"] {
  color: #a80707;
  shape: hexagon;
}

/* Deus / Patrono / Entidade */
element["element type"="Entidade"] {
  color: #fff1a5;
  shape: circle;
}

/* Item / Artefato */
element["element type"="Item"] {
  color: #fffc00;
  shape: diamond;
}

/* Evento */
element["element type"="Evento"] {
  color: white;
  shape: circle;
}

/* Condição */
element["element type"="Condição"] {
  color: purple;
  shape: circle;
}

/* Líder */
connection["connection type"="Lider"] {
  color: #f67c49;
}

/* Membro */
connection["connection type"="Membro"] {
  color: #f67c49;
  style: dashed;
}

/* Parente */
connection["connection type"="Parente"] {
  color: #3596c0;
}

/* Pertence */
connection["connection type"="Pertence"] {
  color: #3596c0;
  style: dashed;
}

/* Amigo */
connection["connection type"="Amigo"] {
  color: #00682a;
}

/* Inimigo */
connection["connection type"="Inimigo"] {
  color: #FF0000;
}

/* Patrono */
connection["connection type"="Patrono"] {
  color: #74c89e;
}

/* Devoto */
connection["connection type"="Devoto"] {
  color: #74c89e;
  style: dashed;
}

/* Rumor */
connection["connection type"="Rumor"] {
  color: purple;
  style: dashed;
}

/* Conexão Não Classificada */
connection["connection type"="Conexão Não Classificada"] {
  color: #ffffff;
  style: dashed;
}

element["status"="Morto"], element["status"="Morto?"] {
  opacity: 0.3;
  border-width: 5;
  border-color: black;
  label: "{{label}} (Morto)";
}

element["status"="Destruido"], element["status"="Destruido?"] {
  opacity: 0.5;
  border-width: 5;
  border-color: Orange;
  label: "{{label}} (Destruido)";
}

element["status"="Desconhecido"], element["status"="Desconhecido?"] {
  opacity: 0.7;
  border-width: 5;
  border-color: Green;
  label: "{{label}} (Desconhecido)";
}
